/**
 * The memory-recall eval's corpus contract (`scripts/eval/memory-recall-corpus.json`).
 *
 * Shared by the harvester that writes the fixture and the runner that scores against it.
 */

import { fileURLToPath } from "node:url";

/** Generated by the harvester — real notes and real conversation. Do not hand-edit. */
export const CORPUS_PATH = fileURLToPath(new URL("./memory-recall-corpus.json", import.meta.url));
/** Hand-authored, and the part that carries the judgement. Kept out of the generated file. */
export const CASES_PATH = fileURLToPath(new URL("./memory-recall-cases.json", import.meta.url));

/** One note from the markdown memory graph, flattened to what recall actually scores. */
export interface NoteFixture {
  name: string;
  type: string;
  description: string;
  body: string;
  /** ISO timestamp — rendered into the primer line, so it is part of the measured output. */
  updated: string;
}

/** One captured channel message, aged relative to the corpus's notional "now". */
export interface EntryFixture {
  messageId: string;
  /** Minutes before "now". The store's TTL is measured against this, reproducibly. */
  ageMinutes: number;
  authorId: string;
  authorName: string;
  content: string;
  kind: "user" | "beckett";
}

export interface ChannelFixture {
  channelId: string;
  name: string | null;
  guildId: string | null;
  entries: EntryFixture[];
}

/**
 * One measured case: a fact that was genuinely stated, and the natural question a person would
 * later ask that ought to surface it.
 *
 *   - `kind: "memory"` — `expect` is a note name in {@link MemoryRecallCorpus.notes}.
 *   - `kind: "channel"` — `expect` is a messageId; `channelId` is the room the question is
 *     ASKED IN, which is what makes "already said in this channel" measurable.
 */
export interface RecallCase {
  id: string;
  kind: "memory" | "channel";
  question: string;
  expect: string;
  /** Required for channel cases: where the question is asked. */
  channelId?: string;
  /** Free-text note on what this case is probing. */
  probes?: string;
}

export interface MemoryRecallCorpus {
  version: number;
  description: string;
  notes: NoteFixture[];
  channels: ChannelFixture[];
}
